/**
 * The AI use case catalogue: real Fruition builds, client names withheld.
 *
 * The records are generated by `scripts/import-ai-use-cases.mjs` from the
 * catalogue draft and live in `public/data/ai-use-cases/` (one file per
 * industry plus `index.json`). Read them through `./data`, never by importing
 * the JSON: an import would bundle about 1 MB of copy into the site Worker.
 */

/** How a step in the future-state process is drawn. */
export type ProcessStepKind = "start" | "end" | "task" | "auto" | "ai" | "system" | "decision"

export interface ProcessStep {
  id: string
  /** One of the process's `lanes`: who or what performs the step. */
  lane: string
  label: string
  kind: ProcessStepKind
}

/** `[from, to]`, or `[from, to, label]` for a labelled branch ("Yes", "No"). */
export type ProcessEdge = [string, string] | [string, string, string]

export interface UseCaseProcess {
  title: string
  lanes: string[]
  /** In the order the work happens. */
  steps: ProcessStep[]
  flow: ProcessEdge[]
}

export interface UseCase {
  /** Stable anchor id, e.g. `uc-8f0364dd`. */
  id: string
  /** Industry filter key (see `IndustryMeta.key`). */
  industry: string
  /** Department filter keys (see `UseCaseIndex.departments`). */
  departments: string[]
  /** Solution type filter keys (see `UseCaseIndex.solutionTypes`). */
  solutionTypes: string[]
  /** The build includes an AI step. */
  ai: boolean
  /** A build Fruition runs on its own business. */
  own: boolean
  /** Industry name, or "Built for Fruition" on Fruition's own builds. */
  kicker: string
  /** The kind of organisation, or the build's name for Fruition's own builds. */
  title: string
  summary: string
  metric?: string
  teams: string[]
  challenge: string
  outcome?: string
  timeframe?: string
  boards: string[]
  automations: string[]
  integrations: string[]
  process?: UseCaseProcess
}

/** What a catalogue tile shows before "See the build" is opened. */
export type UseCaseTile = Pick<
  UseCase,
  | "id"
  | "industry"
  | "departments"
  | "solutionTypes"
  | "ai"
  | "own"
  | "kicker"
  | "title"
  | "summary"
  | "metric"
  | "teams"
  | "integrations"
>

export interface IndustryMeta {
  /** Filter key used on the records, e.g. `realestate`. */
  key: string
  /** URL segment under /ai-use-cases, e.g. `real-estate`. */
  slug: string
  name: string
  count: number
  aiCount: number
}

export interface UseCaseFaq {
  question: string
  answer: string
}

export interface IndustryUseCases extends IndustryMeta {
  seoTitle: string
  seoDescription: string
  heading: string
  intro: string
  faq: UseCaseFaq[]
  useCases: UseCase[]
}

export interface UseCaseIndex {
  /** The draft file the data was imported from. */
  source: string
  total: number
  aiCount: number
  ownCount: number
  /** Use case ids in the hub's display order, which mixes industries. */
  order: string[]
  /** Department key -> label, in display order. */
  departments: Record<string, string>
  /** Solution type key -> label, in display order. */
  solutionTypes: Record<string, string>
  industries: IndustryMeta[]
}

export const USE_CASES_PATH = "/ai-use-cases"
export const USE_CASES_DATA_PATH = "/data/ai-use-cases"

/** In-page anchor of the use case section on each industry landing page. */
export const USE_CASES_ANCHOR = "ai-use-cases"

/**
 * Where each catalogue industry's use cases live now. The per-industry
 * /ai-use-cases/<slug> pages are retired (301 to these, see ./retired.ts);
 * the use cases sit in a `vcUseCases` section on the industry's own page.
 * Education and nonprofit share one catalogue industry; the education page is
 * the primary home and /industries/nonprofits carries the same section.
 * `cross-industry` has no industry page: it lives in the hub.
 */
export const INDUSTRY_PAGES: Record<string, string> = {
  construction: "/monday-for-construction",
  "education-nonprofit": "/industries/education",
  "financial-services": "/industries/financial-services",
  government: "/monday-for-government",
  healthcare: "/industries/healthcare",
  logistics: "/industries/transport-logistics",
  manufacturing: "/monday-for-manufacturing",
  "professional-services": "/monday-for-professional-services",
  "real-estate": "/monday-for-real-estate",
  "retail-ecommerce": "/monday-for-retail",
  "technology-saas": "/industries/technology-saas",
}

/** The hub with one industry preselected (`?industry=` takes the industry key). */
export function hubIndustryHref(industryKey: string): string {
  return `${USE_CASES_PATH}?industry=${encodeURIComponent(industryKey)}#catalogue`
}

/** An industry's use cases: its landing page section, or the filtered hub when it has no page. */
export function industryHref(industry: Pick<IndustryMeta, "slug" | "key">): string {
  const page = INDUSTRY_PAGES[industry.slug]
  return page ? `${page}#${USE_CASES_ANCHOR}` : hubIndustryHref(industry.key)
}

/** "See the build": the hub with the case's industry preselected and its build opened (`#uc-…`). */
export function caseAnchorHref(industryKey: string, id: string): string {
  return `${USE_CASES_PATH}?industry=${encodeURIComponent(industryKey)}#${id}`
}

export function toTile(uc: UseCase): UseCaseTile {
  const { id, industry, departments, solutionTypes, ai, own, kicker, title, summary, metric, teams, integrations } =
    uc
  return {
    id,
    industry,
    departments,
    solutionTypes,
    ai,
    own,
    kicker,
    title,
    summary,
    teams,
    integrations,
    ...(metric ? { metric } : {}),
  }
}
